import React, { useState, useEffect } from "react";

const ProfilePage = () => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Mock fetching user data
        setTimeout(() => {
            setUser({
                contact: {
                    name: "Alex Rivera",
                    designation: "Chief Technology Officer",
                    email: "alex.r@nexus.com",
                    mobile: "+1 (555) 000-1234",
                    city: "San Francisco",
                    state: "California",
                    image: null
                },
                company: {
                    company_name: "Nexus Systems Intl.",
                    database_name: "NODE_US_01"
                }
            });
            setLoading(false);
        }, 1000);
    }, []);

    if (loading) return <div style={{ padding: 50, textAlign: "center" }}>Loading Universe...</div>;

    const getInitials = (name) => {
        const parts = name.trim().split(" ");
        return parts.length > 1
            ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
            : parts[0][0].toUpperCase();
    };

    const container = {
        fontFamily: "'Plus Jakarta Sans', sans-serif",
        padding: "20px",
        maxWidth: "1100px",
        margin: "auto",
        backgroundColor: "#fbfcfe",
        minHeight: "100vh",
    };

    const hero = {
        background: "#fff",
        borderRadius: "24px",
        padding: "20px",
        display: "flex",
        flexDirection: "column", // stacked for mobile
        alignItems: "center",
        gap: "15px",
        boxShadow: "0 10px 30px -10px rgba(0,0,0,0.05)",
        marginBottom: "20px",
        border: "1px solid #f1f5f9",
    };

    const avatar = {
        width: "100px",
        height: "100px",
        borderRadius: "50%",
        background: "linear-gradient(135deg, #4f46e5, #818cf8)",
        color: "white",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "32px",
        fontWeight: "800",
        boxShadow: "0 10px 20px -5px rgba(79, 70, 229, 0.3)",
        objectFit: "cover",
        cursor: "pointer"
    };

    const bentoGrid = {
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
        gap: "15px",
    };

    const card = (isLarge = false, isLogout = false) => ({
        background: isLogout ? "#fff1f0" : isLarge ? "linear-gradient(135deg, #4f46e5, #6366f1)" : "#fff",
        color: isLarge || isLogout ? (isLogout ? "#ff4d4f" : "#fff") : "#475569",
        padding: "20px",
        borderRadius: "20px",
        border: isLogout ? "1px solid #ffa39e" : "1px solid #f1f5f9",
        gridColumn: isLarge ? "span 2" : "span 1",
        transition: "all 0.3s ease",
        cursor: "pointer",
    });

    const pillStyle = {
        background: "#eef2ff",
        color: "#4f46e5",
        padding: "8px 15px",
        borderRadius: "12px",
        fontSize: "13px",
        fontWeight: "600",
        display: "flex",
        alignItems: "center",
        gap: "8px",
    };

    const iconBox = (light = false, danger = false) => ({
        width: "40px",
        height: "40px",
        borderRadius: "12px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        marginBottom: "15px",
        background: light ? "rgba(255,255,255,0.2)" : danger ? "rgba(255,77,79,0.1)" : "#f8fafc",
        color: light ? "white" : danger ? "#ff4d4f" : "#4f46e5",
    });

    const labelStyle = (light = false) => ({
        fontSize: "11px",
        textTransform: "uppercase",
        letterSpacing: "1px",
        fontWeight: "800",
        marginBottom: "8px",
        opacity: light ? 0.8 : 0.5,
    });

    return (
        <div style={container}>
            {/* Hero */}
            <div style={hero}>
                <div style={avatar}>{user.contact.image ? <img src={user.contact.image} alt="Profile" style={{ width: "100%", height: "100%", borderRadius: "50%" }} /> : getInitials(user.contact.name)}</div>
                <div style={{ textAlign: "center" }}>
                    <h1 style={{ margin: 0, fontSize: "28px", color: "#0f172a" }}>{user.contact.name}</h1>
                    <p style={{ color: "#4f46e5", fontWeight: 700, textTransform: "uppercase", margin: "5px 0", fontSize: "12px" }}>{user.contact.designation}</p>
                    <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "10px", marginTop: "10px" }}>
                        <div style={pillStyle}><i className="fa-solid fa-envelope"></i> {user.contact.email}</div>
                        <div style={pillStyle}><i className="fa-solid fa-phone"></i> {user.contact.mobile}</div>
                    </div>
                </div>
            </div>

            {/* Bento Grid */}
            <div style={bentoGrid}>
                <div style={card(true, false)}>
                    <div style={iconBox(true)}><i className="fa-solid fa-building"></i></div>
                    <div style={labelStyle(true)}>Primary Organization</div>
                    <div style={{ fontSize: "24px", fontWeight: 700 }}>{user.company.company_name}</div>
                </div>

                <div style={card()}>
                    <div style={iconBox()}><i className="fa-solid fa-database"></i></div>
                    <div style={labelStyle()}>System Node</div>
                    <div style={{ fontSize: "18px", fontWeight: 700 }}>{user.company.database_name}</div>
                </div>

                <div style={card()}>
                    <div style={iconBox()}><i className="fa-solid fa-location-dot"></i></div>
                    <div style={labelStyle()}>Location</div>
                    <div style={{ fontSize: "18px", fontWeight: 700 }}>{user.contact.city}, {user.contact.state}</div>
                </div>

                <a href="/logout" style={{ textDecoration: "none" }}>
                    <div style={card(false, true)}>
                        <div style={iconBox(false, true)}><i className="fa-solid fa-power-off"></i></div>
                        <div style={labelStyle()}>Security</div>
                        <div style={{ fontSize: "18px", fontWeight: 700 }}>Terminate Session</div>
                    </div>
                </a>
            </div>
        </div>
    );
};

export default ProfilePage;
